#include <print>
#include <string>

int main() {
    int reported = 0, cur = 1;
    for (; reported < 15; ++cur) {
        bool skip = (cur % 7 == 0) || std::to_string(cur).find('7') != std::string::npos;
        if (skip) {
            std::println("被跳过的数：{}", cur);
        } else {
            ++reported;
        }
    }
    std::println("报满 15 个，最后一个报出的是 {}", cur - 1);
    return 0;
}

