int main() {
    int reported = 0;
    for (int cur = 1; reported < 20; ++cur) {
        bool skip = (cur % 7 == 0) || std::to_string(cur).find('7') != std::string::npos;
        if (!skip) {
            ++reported;
        } else {
            std::println("第 {} 个正常数之后，跳过了 {}", reported, cur);
        }
    }
    return 0;
}
